150:    /// Whitepaper lifecycle steps 10–12: persist the sealed blob, drop stale
151:    /// hash versions of the same plugin, rebuild the reflection index, and
152:    /// commit the catalog manifest.
153:    pub fn upsert_blob(&mut self, blob: &PluginObjectBlob) -> io::Result<PathBuf> {
154:        let path = blob.write_to_dir(&self.dir)?;
155:        // Remove superseded hash versions on disk.
156:        let prefix = format!("{}.", blob.manifest.plugin_id);
157:        for e in std::fs::read_dir(&self.dir)? {
158:            let p = e?.path();
159:            if p != path
160:                && let Some(name) = p.file_name().and_then(|n| n.to_str())
161:                && name.starts_with(&prefix)
162:                && name.ends_with(".blob")
163:            {
164:                let _ = std::fs::remove_file(&p);
165:            }
166:        }
167:        let bytes = std::fs::read(&path)?;
168:        let entry = index_entry(path.clone(), bytes)
169:            .map_err(|e| io::Error::new(io::ErrorKind::InvalidData, e))?;
170:        self.entries.insert(blob.manifest.plugin_id.clone(), entry);
171:        self.write_manifest()?;
172:        Ok(path)
173:    }
174:
175:    /// Inverse lifecycle: deactivate the plugin object, delete the artifact,
176:    /// stop advertising its services, commit the catalog manifest.
177:    pub fn remove_blob(&mut self, plugin_id: &str) -> io::Result<bool> {
178:        match self.entries.remove(plugin_id) {
179:            Some(entry) => {
180:                if entry.path.exists() {
181:                    std::fs::remove_file(&entry.path)?;
182:                }
183:                self.write_manifest()?;
184:                Ok(true)
185:            }
186:            None => Ok(false),
187:        }
188:    }
189:
190:    /// Drop every blob whose plugin id is NOT in `keep`. Returns the removed
191:    /// plugin ids. This is how a full re-seal deregisters plugins that no
192:    /// longer exist — a blob in the catalog IS the plugin, so a plugin that
193:    /// vanished from the build must vanish from the catalog.
194:    pub fn retain_plugins(
195:        &mut self,
196:        keep: &std::collections::HashSet<String>,
197:    ) -> io::Result<Vec<String>> {
198:        let stale: Vec<String> = self
199:            .entries
200:            .keys()
201:            .filter(|id| !keep.contains(*id))
202:            .cloned()
203:            .collect();
204:        for id in &stale {
205:            if let Some(entry) = self.entries.remove(id)
206:                && entry.path.exists()
207:            {
208:                std::fs::remove_file(&entry.path)?;
209:            }
210:        }
211:        if !stale.is_empty() {
212:            self.write_manifest()?;
213:        }
214:        Ok(stale)
215:    }
216:
217:    /// Blake3 leaf-fold over the sorted `(plugin_id, schema_hash)` pairs —
218:    /// the single catalog identity value.
219:    pub fn catalog_hash(&self) -> String {
220:        let mut leaves: Vec<(&String, &String)> = self
221:            .entries
222:            .iter()
223:            .map(|(id, e)| (id, &e.manifest.schema_hash))
224:            .collect();
225:        leaves.sort();
226:        let mut h = blake3::Hasher::new();
227:        for (id, hash) in leaves {
228:            h.update(id.as_bytes());
229:            h.update(b"\0");
230:            h.update(hash.as_bytes());
231:            h.update(b"\0");
232:        }
233:        h.finalize().to_hex().to_string()
234:    }
235:
236:    /// Write `.manifest.json` atomically (tmp + rename), LAST after blob
237:    /// mutations — the commit point consumers use for change detection.
238:    fn write_manifest(&self) -> io::Result<()> {
239:        let path = self.dir.join(MANIFEST_FILENAME);
240:        let generation = Self::read_manifest_generation(&path).wrapping_add(1);
241:        // The hash this write supersedes. A genesis minted moments before a
242:        // reseal binds it, and would otherwise name a catalog nothing publishes
243:        // any more — so the manifest carries a two-deep window and verification
244:        // accepts either. Deliberately a window, not a history: the durable
245:        // record of what a session ran against is the chain, not this file.
246:        let previous_catalog_hash = Self::read_catalog_hash(&self.dir).unwrap_or_default();
247:        let mut plugins = std::collections::BTreeMap::new();
248:        for (id, e) in &self.entries {
249:            plugins.insert(id.clone(), e.manifest.schema_hash.clone());
250:        }
251:        let manifest = serde_json::json!({
252:            "catalog_hash": self.catalog_hash(),
253:            "previous_catalog_hash": previous_catalog_hash,
254:            "generation": generation,
255:            "plugins": plugins,
256:        });
257:        let bytes = serde_json::to_vec_pretty(&manifest)
258:            .map_err(|e| io::Error::new(io::ErrorKind::InvalidData, e))?;
259:        let tmp = self.dir.join(format!("{MANIFEST_FILENAME}.tmp"));
260:        std::fs::write(&tmp, &bytes)?;
261:        std::fs::rename(&tmp, &path)?;
262:        Ok(())
263:    }
264:
265:    /// Current manifest `generation`, or 0 if absent/unparsable. The next
266:    /// write uses `generation + 1` so readers get a monotonic staleness marker.
267:    fn read_manifest_generation(path: &Path) -> u64 {
268:        std::fs::read(path)
269:            .ok()
270:            .and_then(|b| serde_json::from_slice::<serde_json::Value>(&b).ok())
271:            .and_then(|v| v.get("generation").and_then(serde_json::Value::as_u64))
272:            .unwrap_or(0)
273:    }
274:
275:    /// Read the published `catalog_hash` from a catalog dir without loading
276:    /// any blobs. Consumers use this for arrival-triggered change detection —
277:    /// read, never re-hash.
278:    pub fn read_catalog_hash(dir: &Path) -> Option<String> {
279:        let bytes = std::fs::read(dir.join(MANIFEST_FILENAME)).ok()?;
280:        let v: serde_json::Value = serde_json::from_slice(&bytes).ok()?;
281:        v.get("catalog_hash")
282:            .and_then(serde_json::Value::as_str)
283:            .map(String::from)
284:    }
