286:    /// Reflection `ListServices`: only active blobs, sorted.
287:    pub fn list_services(&self) -> Vec<String> {
288:        let mut v: Vec<String> = self
289:            .entries
290:            .values()
291:            .flat_map(|e| e.manifest.grpc.services.iter().cloned())
292:            .collect();
293:        v.sort();
294:        v
295:    }
