297:    pub fn active_plugins(&self) -> Vec<String> {
298:        let mut v: Vec<String> = self.entries.keys().cloned().collect();
299:        v.sort();
300:        v
301:    }
302:
303:    /// Reflection `file_by_filename`: borrowed `FileDescriptorProto` bytes.
304:    pub fn file_by_filename(&self, filename: &str) -> Option<&[u8]> {
305:        self.entries.values().find_map(|e| {
306:            e.files
307:                .get(filename)
308:                .map(|(off, len)| &e.bytes[*off..*off + *len])
309:        })
310:    }
311:
312:    /// Reflection `file_containing_symbol`.
313:    pub fn symbol_by_name(&self, symbol: &str) -> Option<&[u8]> {
314:        self.entries.values().find_map(|e| {
315:            e.symbols
316:                .get(symbol)
317:                .and_then(|file| e.files.get(file))
318:                .map(|(off, len)| &e.bytes[*off..*off + *len])
319:        })
320:    }
321:
322:    pub fn manifest(&self, plugin_id: &str) -> Option<&BlobManifest> {
323:        self.entries.get(plugin_id).map(|e| &e.manifest)
324:    }
325:
326:    pub fn dir(&self) -> &Path {
327:        &self.dir
328:    }
329:
330:    /// Paths of all active blob artifacts (input to btrfs sealing).
331:    pub fn blob_paths(&self) -> Vec<PathBuf> {
332:        let mut v: Vec<PathBuf> = self.entries.values().map(|e| e.path.clone()).collect();
333:        v.sort();
334:        v
335:    }
