6://!
7://! `subid` is the stable human-readable operational taxonomy key; the paired
8://! immutable `uuid` and compliance mappings live in metadata, never in the
9://! subid string.
10:
11:pub const CATEGORIES: &[&str] = &["src", "prj", "sch", "mut", "obs", "evt", "exp"];
12:
13:/// OSCAL component-type vocabulary accepted in position 2.
14:pub const COMPONENT_TYPES: &[&str] = &[
15:    "service",
16:    "software",
17:    "network",
18:    "hardware",
19:    "data",
20:    "policy",
21:    "process",
22:    "plan",
23:    "guidance",
24:    "standard",
25:    "validation",
26:    "system",
27:    "interconnection",
28:];
29:
30:pub fn validate_subid(subid: &str) -> Result<(), String> {
31:    let (base, version) = match subid.split_once('@') {
32:        Some((b, v)) => (b, Some(v)),
33:        None => (subid, None),
34:    };
35:
36:    if let Some(v) = version {
37:        let ok = v.len() >= 2 && v.starts_with('v') && v[1..].chars().all(|c| c.is_ascii_digit());
38:        if !ok {
39:            return Err(format!("{subid}: version must be @vN, got @{v}"));
40:        }
41:    }
42:
43:    let segments: Vec<&str> = base.split('.').collect();
44:    if segments.len() < 4 || segments.len() > 5 {
45:        return Err(format!(
46:            "{subid}: expected category.component-type.subject.verb[.facet], got {} segments",
47:            segments.len()
48:        ));
49:    }
50:
51:    if !CATEGORIES.contains(&segments[0]) {
52:        return Err(format!(
53:            "{subid}: category {:?} not one of {CATEGORIES:?}",
54:            segments[0]
55:        ));
56:    }
