pub fn verify_btrfs_image(path: &Path) -> io::Result<bool> {
    use std::io::{Read, Seek, SeekFrom};
    let mut f = std::fs::File::open(path)?;
    if f.metadata()?.len() < BTRFS_MAGIC_OFFSET + 8 {
        return Ok(false);
    }
    f.seek(SeekFrom::Start(BTRFS_MAGIC_OFFSET))?;
    let mut buf = [0u8; 8];
    f.read_exact(&mut buf)?;
    Ok(&buf == BTRFS_MAGIC)
}

pub fn which_mkfs() -> Option<PathBuf> {
    std::env::var_os("PATH").and_then(|paths| {
        std::env::split_paths(&paths)
            .map(|d| d.join("mkfs.btrfs"))
            .find(|p| p.is_file())
    })
}

fn run_mkfs(args: &[String]) -> io::Result<()> {
    let out = Command::new("mkfs.btrfs").args(args).output()?;
    if !out.status.success() {
        return Err(io::Error::other(format!(
            "mkfs.btrfs failed to create plugin subvolumes: {}",
            String::from_utf8_lossy(&out.stderr).trim()
        )));
    }
    Ok(())
}

fn staging_dir(image_path: &Path) -> io::Result<PathBuf> {
    let parent = image_path.parent().unwrap_or(Path::new("."));
    let dir = parent.join(format!(
        ".opblob-staging-{}",
        std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .map(|d| d.as_nanos())
            .unwrap_or(0)
    ));
    if dir.exists() {
        std::fs::remove_dir_all(&dir)?;
    }
    std::fs::create_dir_all(&dir)?;
    Ok(dir)
}

fn validate_plugin_component(plugin_id: &str) -> io::Result<()> {
    if plugin_id.is_empty()
        || plugin_id.len() > 128
        || matches!(plugin_id, "." | "..")
        || !plugin_id
            .bytes()
            .all(|c| c.is_ascii_alphanumeric() || matches!(c, b'_' | b'-' | b'.'))
    {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            "plugin ID must be a single safe path component",
        ));
    }
    Ok(())
}

#[cfg(test)]
mod security_tests {
    use super::validate_plugin_component;

    #[test]
    fn plugin_id_cannot_escape_staging() {
        for id in ["../outside", "/outside", "a/b", ".", "a\\b", ""] {
            assert!(validate_plugin_component(id).is_err(), "{id}");
        }
        assert!(validate_plugin_component("valid_plugin-1").is_ok());
    }
}

