381:fn field_diffs(d: &mut Vec<String>, prefix: &str, r: &FieldSchema, v: &FieldSchema) {
382:    if type_tag(&r.field_type) != type_tag(&v.field_type) {
383:        d.push(format!(
384:            "{prefix}.type: {} -> {}",
385:            type_tag(&r.field_type),
386:            type_tag(&v.field_type)
387:        ));
388:    }
389:    if r.required != v.required {
390:        d.push(format!(
391:            "{prefix}.required: {} -> {}",
392:            r.required, v.required
393:        ));
394:    }
395:    if r.description != v.description {
396:        d.push(format!(
397:            "{prefix}.description: {:?} -> {:?}",
398:            r.description, v.description
399:        ));
400:    }
401:    if r.default != v.default {
402:        d.push(format!(
403:            "{prefix}.default: {:?} -> {:?}",
404:            r.default, v.default
405:        ));
406:    }
407:    if r.example != v.example {
408:        d.push(format!(
409:            "{prefix}.example: {:?} -> {:?}",
410:            r.example, v.example
411:        ));
412:    }
413:    if constraint_tags(&r.constraints) != constraint_tags(&v.constraints) {
414:        d.push(format!(
415:            "{prefix}.constraints: {:?} -> {:?}",
416:            constraint_tags(&r.constraints),
417:            constraint_tags(&v.constraints)
418:        ));
419:    }
420:    if r.read_only != v.read_only {
421:        d.push(format!(
422:            "{prefix}.read_only: {} -> {}",
423:            r.read_only, v.read_only
424:        ));
425:    }
426:    field_type_diffs(d, prefix, &r.field_type, &v.field_type);
427:}
