429:fn field_type_diffs(d: &mut Vec<String>, prefix: &str, r: &FieldType, v: &FieldType) {
430:    match (r, v) {
431:        (FieldType::JsonSchema(left), FieldType::JsonSchema(right)) if left != right => {
432:            d.push(format!("{prefix}: exact schema changed"));
433:        }
434:        (FieldType::Map(r_inner), FieldType::Map(v_inner)) => {
435:            field_type_diffs(d, &format!("{prefix}{{value}}"), r_inner, v_inner);
436:        }
437:        (FieldType::Array(r_inner), FieldType::Array(v_inner)) => {
438:            field_type_diffs(d, &format!("{prefix}[]"), r_inner, v_inner);
439:        }
440:        (FieldType::Object(r_map), FieldType::Object(v_map)) => {
441:            let keys: std::collections::BTreeSet<&String> =
442:                r_map.keys().chain(v_map.keys()).collect();
443:            for k in keys {
444:                match (r_map.get(k), v_map.get(k)) {
445:                    (Some(rf), Some(vf)) => field_diffs(d, &format!("{prefix}.{k}"), rf, vf),
446:                    (Some(_), None) => {
447:                        d.push(format!("{prefix}.{k}: DROPPED (in reference, not derived)"))
448:                    }
449:                    (None, Some(_)) => {
450:                        d.push(format!("{prefix}.{k}: ADDED (in derived, not reference)"))
451:                    }
452:                    (None, None) => {}
453:                }
454:            }
455:        }
456:        (FieldType::OneOf(r_branches), FieldType::OneOf(v_branches)) => {
457:            if r_branches.len() != v_branches.len() {
458:                d.push(format!(
459:                    "{prefix}: one_of branch count differs ({} vs {})",
460:                    r_branches.len(),
461:                    v_branches.len()
462:                ));
463:            }
464:            for (i, (rb, vb)) in r_branches.iter().zip(v_branches.iter()).enumerate() {
465:                field_type_diffs(d, &format!("{prefix}|{i}"), rb, vb);
466:            }
467:        }
468:        _ => {}
469:    }
470:}
