472:fn type_tag(t: &FieldType) -> String {
473:    match t {
474:        FieldType::String => "string".into(),
475:        FieldType::Integer => "integer".into(),
476:        FieldType::Float => "float".into(),
477:        FieldType::Boolean => "boolean".into(),
478:        FieldType::JsonSchema(_) => "json_schema".into(),
479:        FieldType::Any => "any".into(),
480:        FieldType::Enum(_) => "enum".into(),
481:        FieldType::OneOf(branches) => {
482:            let mut tags: Vec<String> = branches.iter().map(type_tag).collect();
483:            tags.sort();
484:            format!("one_of<{}>", tags.join("|"))
485:        }
486:        FieldType::Map(i) => format!("map<string,{}>", type_tag(i)),
487:        FieldType::Array(i) => format!("array<{}>", type_tag(i)),
488:        FieldType::Object(m) => {
489:            let mut entries: Vec<String> = m
490:                .iter()
491:                .map(|(k, v)| format!("{k}:{}", type_tag(&v.field_type)))
492:                .collect();
493:            entries.sort();
494:            format!("object{{{}}}", entries.join(","))
495:        }
496:    }
497:}
