499:fn constraint_tags(cs: &[Constraint]) -> Vec<String> {
500:    let mut v: Vec<String> = cs
501:        .iter()
502:        .map(|c| match c {
503:            Constraint::Min { value } => format!("min:{value}"),
504:            Constraint::Max { value } => format!("max:{value}"),
505:            Constraint::Pattern { regex } => format!("pattern:{regex}"),
506:            Constraint::OneOf { .. } => "oneof".into(),
507:            Constraint::RequiresField { field } => format!("requires:{field}"),
508:            Constraint::Custom { validator } => format!("custom:{validator}"),
509:        })
510:        .collect();
511:    v.sort();
512:    v
513:}
